META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–3: ವಿದ್ಯೆಗಳ ರಾಜ, ರಹಸ್ಯಗಳ ರಾಜ; 4–10: ಭಗವಂತ ಇಡೀ ಜಗತ್ತನ್ನು ವ್ಯಾಪಿಸಿ ಧರಿಸಿದ್ದಾನೆ, ಆದರೂ ಅದಕ್ಕೆ ಬಂಧಿತನಲ್ಲ; 11–15: ಮೂಢರು ಅವನನ್ನು ಅವಮಾನಿಸುತ್ತಾರೆ, ಮಹಾತ್ಮರು ಅವನನ್ನು ಉಪಾಸಿಸುತ್ತಾರೆ; 16–19: "ನಾನೇ ಯಜ್ಞ, ತಂದೆ, ಗತಿ"; 20–25: ಸ್ವರ್ಗ ಶಾಶ್ವತವಲ್ಲ, ಪ್ರತಿ ಉಪಾಸಕ ತಾನು ಪೂಜಿಸುವುದನ್ನೇ ಸೇರುತ್ತಾನೆ; 26–28: ಒಂದು ಎಲೆ, ಒಂದು ಹೂವು, ಒಂದು ಹಣ್ಣು, ಮತ್ತು ಎಲ್ಲವನ್ನೂ ಅರ್ಪಿಸುವುದು; 29–34: ಭಗವಂತ ಎಲ್ಲರಿಗೂ ಸಮಾನ, ಅವನ ಭಕ್ತ ಎಂದಿಗೂ ನಾಶವಾಗುವುದಿಲ್ಲ.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ನೀನು ದೋಷ ಹುಡುಕುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಅತ್ಯಂತ ರಹಸ್ಯವಾದ ಈ ಜ್ಞಾನವನ್ನು ಅನುಭವ ಸಹಿತ ನಿನಗೆ ಹೇಳುತ್ತೇನೆ. ಇದನ್ನು ತಿಳಿದರೆ ನೀನು ಅಶುಭದಿಂದ ಮುಕ್ತನಾಗುತ್ತೀಯ.',
2: 'ಇದು ವಿದ್ಯೆಗಳ ರಾಜ, ರಹಸ್ಯಗಳ ರಾಜ, ಅತ್ಯುತ್ತಮ ಮತ್ತು ಪವಿತ್ರಗೊಳಿಸುವಂಥದ್ದು. ಇದನ್ನು ನೇರವಾಗಿ ಅನುಭವಿಸಬಹುದು; ಇದು ಧರ್ಮಕ್ಕೆ ಅನುಗುಣವಾದುದು, ಆಚರಿಸಲು ಬಹಳ ಸುಲಭ, ಅವಿನಾಶಿ.',
3: 'ಹೇ ಪರಂತಪ, ಈ ಧರ್ಮದಲ್ಲಿ ಶ್ರದ್ಧೆಯಿಲ್ಲದವರು ನನ್ನನ್ನು ಸೇರದೆ ಮೃತ್ಯುಮಯ ಸಂಸಾರದ ಮಾರ್ಗಕ್ಕೆ ಹಿಂತಿರುಗುತ್ತಾರೆ.',
4: 'ಈ ಇಡೀ ಜಗತ್ತು ನನ್ನ ಅವ್ಯಕ್ತ ರೂಪದಿಂದ ವ್ಯಾಪಿಸಿದೆ. ಎಲ್ಲ ಜೀವಿಗಳೂ ನನ್ನಲ್ಲಿವೆ, ಆದರೆ ನಾನು ಅವುಗಳಲ್ಲಿಲ್ಲ.',
5: 'ಆದರೂ ಜೀವಿಗಳು ನನ್ನಲ್ಲಿಲ್ಲ. ನನ್ನ ದೈವೀ ಯೋಗಶಕ್ತಿಯನ್ನು ನೋಡು! ನನ್ನ ಸ್ವರೂಪ ಜೀವಿಗಳನ್ನು ಹುಟ್ಟಿಸಿ ಧರಿಸುತ್ತದೆ, ಆದರೂ ಅವುಗಳಲ್ಲಿ ಇರುವುದಿಲ್ಲ.',
6: 'ಎಲ್ಲೆಡೆ ಬೀಸುವ ಬಲವಾದ ಗಾಳಿ ಸದಾ ಆಕಾಶದಲ್ಲಿರುವಂತೆ, ಎಲ್ಲ ಜೀವಿಗಳೂ ನನ್ನಲ್ಲಿವೆ ಎಂದು ತಿಳಿ.',
7: 'ಹೇ ಕೌಂತೇಯ, ಕಲ್ಪದ ಕೊನೆಯಲ್ಲಿ ಎಲ್ಲ ಜೀವಿಗಳೂ ನನ್ನ ಪ್ರಕೃತಿಯಲ್ಲಿ ಲೀನವಾಗುತ್ತವೆ. ಕಲ್ಪದ ಆರಂಭದಲ್ಲಿ ನಾನು ಅವುಗಳನ್ನು ಮತ್ತೆ ಸೃಷ್ಟಿಸುತ್ತೇನೆ.',
8: 'ನನ್ನ ಪ್ರಕೃತಿಯನ್ನು ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡು, ಪ್ರಕೃತಿಗೆ ಅಧೀನವಾದ ಅಸಹಾಯಕ ಈ ಎಲ್ಲ ಜೀವಿಸಮೂಹವನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಸೃಷ್ಟಿಸುತ್ತೇನೆ.',
9: 'ಹೇ ಧನಂಜಯ, ಈ ಕರ್ಮಗಳು ನನ್ನನ್ನು ಬಂಧಿಸುವುದಿಲ್ಲ, ಏಕೆಂದರೆ ನಾನು ಅವುಗಳಲ್ಲಿ ಆಸಕ್ತಿಯಿಲ್ಲದೆ, ಉದಾಸೀನನಂತೆ ಇರುತ್ತೇನೆ.',
10: 'ಹೇ ಕೌಂತೇಯ, ನನ್ನ ಮೇಲ್ವಿಚಾರಣೆಯಲ್ಲಿ ಪ್ರಕೃತಿ ಚರಾಚರಗಳೆಲ್ಲವನ್ನೂ ಹುಟ್ಟಿಸುತ್ತದೆ. ಈ ಕಾರಣದಿಂದಲೇ ಜಗತ್ತು ತಿರುಗುತ್ತಿರುತ್ತದೆ.',
11: 'ನಾನು ಮಾನವ ದೇಹ ಧರಿಸಿದಾಗ ಮೂಢರು ನನ್ನನ್ನು ಅವಮಾನಿಸುತ್ತಾರೆ, ಏಕೆಂದರೆ ಎಲ್ಲ ಜೀವಿಗಳ ಮಹೇಶ್ವರನಾದ ನನ್ನ ಪರಮ ಭಾವವನ್ನು ಅವರು ತಿಳಿಯರು.',
12: 'ಅವರ ಆಸೆಗಳು, ಅವರ ಕರ್ಮಗಳು, ಅವರ ಜ್ಞಾನ ಎಲ್ಲವೂ ವ್ಯರ್ಥ. ವಿವೇಕ ಕಳೆದುಕೊಂಡು ಅವರು ಮೋಹಗೊಳಿಸುವ ರಾಕ್ಷಸೀ ಮತ್ತು ಆಸುರೀ ಪ್ರಕೃತಿಯನ್ನು ಆಶ್ರಯಿಸುತ್ತಾರೆ.',
13: 'ಆದರೆ ಹೇ ಪಾರ್ಥ, ದೈವೀ ಪ್ರಕೃತಿಯನ್ನು ಆಶ್ರಯಿಸಿದ ಮಹಾತ್ಮರು ನನ್ನನ್ನು ಎಲ್ಲ ಜೀವಿಗಳ ಅವಿನಾಶಿ ಮೂಲವೆಂದು ತಿಳಿದು, ಅನನ್ಯ ಮನಸ್ಸಿನಿಂದ ನನ್ನನ್ನು ಭಜಿಸುತ್ತಾರೆ.',
14: 'ಅವರು ಸದಾ ನನ್ನ ಕೀರ್ತನೆ ಮಾಡುತ್ತಾ, ದೃಢವ್ರತದಿಂದ ಪ್ರಯತ್ನಿಸುತ್ತಾ, ಭಕ್ತಿಯಿಂದ ನನಗೆ ನಮಸ್ಕರಿಸುತ್ತಾ, ನಿತ್ಯ ನನ್ನೊಂದಿಗೆ ಕೂಡಿ ನನ್ನನ್ನು ಉಪಾಸಿಸುತ್ತಾರೆ.',
15: 'ಇನ್ನು ಕೆಲವರು ಜ್ಞಾನಯಜ್ಞದಿಂದ ನನ್ನನ್ನು ಉಪಾಸಿಸುತ್ತಾರೆ: ಕೆಲವರು ಒಬ್ಬನೆಂದು, ಕೆಲವರು ತಮಗಿಂತ ಬೇರೆಯಾದವನೆಂದು, ಕೆಲವರು ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಗೂ ಮುಖವಿರುವ ನನ್ನ ಅನೇಕ ರೂಪಗಳಾಗಿ.',
16: 'ನಾನೇ ಕ್ರತು (ವೈದಿಕ ಕರ್ಮ), ನಾನೇ ಯಜ್ಞ, ಪಿತೃಗಳಿಗೆ ಕೊಡುವ ಸ್ವಧಾ ನಾನು, ಔಷಧಿ ನಾನು. ಮಂತ್ರ ನಾನು, ತುಪ್ಪ ನಾನು, ಅಗ್ನಿ ನಾನು, ಆಹುತಿಯೂ ನಾನೇ.',
17: 'ಈ ಜಗತ್ತಿನ ತಂದೆ, ತಾಯಿ, ಧರಿಸುವವನು ಮತ್ತು ಅಜ್ಜ ನಾನು. ತಿಳಿಯಬೇಕಾದುದು, ಪವಿತ್ರಗೊಳಿಸುವುದು, ಓಂಕಾರ, ಋಕ್, ಸಾಮ ಮತ್ತು ಯಜುರ್ವೇದಗಳೂ ನಾನೇ.',
18: 'ನಾನೇ ಗತಿ, ಪೋಷಕ, ಪ್ರಭು, ಸಾಕ್ಷಿ, ನಿವಾಸ, ಶರಣು ಮತ್ತು ಸ್ನೇಹಿತ. ಸೃಷ್ಟಿ, ಪ್ರಳಯ, ಆಧಾರ, ನಿಧಿ ಮತ್ತು ಅವಿನಾಶಿ ಬೀಜವೂ ನಾನೇ.',
19: 'ಹೇ ಅರ್ಜುನ, ನಾನೇ ಶಾಖ ಕೊಡುತ್ತೇನೆ; ಮಳೆಯನ್ನು ತಡೆಯುವವನೂ ಸುರಿಸುವವನೂ ನಾನೇ. ಅಮೃತವೂ ನಾನೇ, ಮೃತ್ಯುವೂ ನಾನೇ, ಸತ್ ಮತ್ತು ಅಸತ್ ಎರಡೂ ನಾನೇ.',
20: 'ಮೂರು ವೇದಗಳನ್ನು ಅನುಸರಿಸುವವರು, ಸೋಮರಸ ಕುಡಿದು ಪಾಪದಿಂದ ಶುದ್ಧರಾದವರು, ಯಜ್ಞಗಳಿಂದ ನನ್ನನ್ನು ಪೂಜಿಸಿ ಸ್ವರ್ಗಕ್ಕೆ ಹೋಗಲು ಪ್ರಾರ್ಥಿಸುತ್ತಾರೆ. ಅವರು ಪುಣ್ಯದಿಂದ ಇಂದ್ರಲೋಕವನ್ನು ಸೇರಿ, ಅಲ್ಲಿ ದೇವತೆಗಳ ದಿವ್ಯ ಭೋಗಗಳನ್ನು ಅನುಭವಿಸುತ್ತಾರೆ.',
21: 'ಆ ವಿಶಾಲ ಸ್ವರ್ಗಲೋಕವನ್ನು ಅನುಭವಿಸಿ, ಪುಣ್ಯ ಮುಗಿದಾಗ ಅವರು ಮರ್ತ್ಯಲೋಕಕ್ಕೆ ಹಿಂತಿರುಗುತ್ತಾರೆ. ಹೀಗೆ ಮೂರು ವೇದಗಳ ಕರ್ಮಕಾಂಡವನ್ನು ಪಾಲಿಸುವ, ಭೋಗಗಳನ್ನು ಬಯಸುವವರು ಬರುತ್ತಾ ಹೋಗುತ್ತಾ ಇರುತ್ತಾರೆ.',
23: 'ಹೇ ಕೌಂತೇಯ, ಇತರ ದೇವತೆಗಳನ್ನು ಶ್ರದ್ಧೆಯಿಂದ ಪೂಜಿಸುವ ಭಕ್ತರೂ ನಿಜವಾಗಿ ನನ್ನನ್ನೇ ಪೂಜಿಸುತ್ತಾರೆ, ಆದರೆ ವಿಧಿಪೂರ್ವಕವಾಗಿ ಅಲ್ಲ.',
24: 'ಏಕೆಂದರೆ ಎಲ್ಲ ಯಜ್ಞಗಳ ಭೋಕ್ತ ಮತ್ತು ಪ್ರಭು ನಾನೇ. ಆದರೆ ಅವರು ನನ್ನನ್ನು ತತ್ತ್ವವಾಗಿ ತಿಳಿಯರು, ಆದ್ದರಿಂದ ಅವರು ಪತನ ಹೊಂದುತ್ತಾರೆ.',
25: 'ದೇವತೆಗಳನ್ನು ಉಪಾಸಿಸುವವರು ದೇವತೆಗಳನ್ನು ಸೇರುತ್ತಾರೆ, ಪಿತೃಗಳನ್ನು ಉಪಾಸಿಸುವವರು ಪಿತೃಗಳನ್ನು, ಭೂತಗಳನ್ನು ಉಪಾಸಿಸುವವರು ಭೂತಗಳನ್ನು, ನನ್ನನ್ನು ಉಪಾಸಿಸುವವರು ನನ್ನನ್ನೇ ಸೇರುತ್ತಾರೆ.',
27: 'ಹೇ ಕೌಂತೇಯ, ನೀನು ಏನು ಮಾಡಿದರೂ, ಏನು ತಿಂದರೂ, ಏನು ಹೋಮ ಮಾಡಿದರೂ, ಏನು ದಾನ ಮಾಡಿದರೂ, ಯಾವ ತಪಸ್ಸು ಮಾಡಿದರೂ, ಅದನ್ನು ನನಗೆ ಅರ್ಪಣೆಯಾಗಿ ಮಾಡು.',
28: 'ಹೀಗೆ ನೀನು ಕರ್ಮಬಂಧನಗಳಿಂದ ಮತ್ತು ಅವುಗಳ ಶುಭಾಶುಭ ಫಲಗಳಿಂದ ಮುಕ್ತನಾಗುತ್ತೀಯ. ಸಂನ್ಯಾಸಯೋಗದಲ್ಲಿ ಸ್ಥಿರವಾದ ಮನಸ್ಸಿನಿಂದ ಮುಕ್ತನಾಗಿ ನನ್ನನ್ನು ಸೇರುತ್ತೀಯ.',
29: 'ನಾನು ಎಲ್ಲ ಜೀವಿಗಳಿಗೂ ಸಮಾನ; ನನಗೆ ಯಾರೂ ದ್ವೇಷಕ್ಕೆ ಅರ್ಹರಲ್ಲ, ಯಾರೂ ವಿಶೇಷ ಪ್ರಿಯರಲ್ಲ. ಆದರೆ ಭಕ್ತಿಯಿಂದ ನನ್ನನ್ನು ಭಜಿಸುವವರು ನನ್ನಲ್ಲಿರುತ್ತಾರೆ, ನಾನು ಅವರಲ್ಲಿರುತ್ತೇನೆ.',
30: 'ಅತ್ಯಂತ ಕೆಟ್ಟ ನಡತೆಯವನಾದರೂ ಅನನ್ಯ ಭಾವದಿಂದ ನನ್ನನ್ನು ಭಜಿಸಿದರೆ, ಅವನನ್ನು ಸಾಧುವೆಂದೇ ಭಾವಿಸಬೇಕು, ಏಕೆಂದರೆ ಅವನು ಸರಿಯಾದ ನಿರ್ಧಾರ ಮಾಡಿದ್ದಾನೆ.',
31: 'ಅವನು ಬೇಗನೆ ಧರ್ಮಾತ್ಮನಾಗಿ ಶಾಶ್ವತ ಶಾಂತಿಯನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಹೇ ಕೌಂತೇಯ, ನನ್ನ ಭಕ್ತ ಎಂದಿಗೂ ನಾಶವಾಗುವುದಿಲ್ಲ ಎಂದು ದೃಢವಾಗಿ ಘೋಷಿಸು.',
32: 'ಹೇ ಪಾರ್ಥ, ನನ್ನನ್ನು ಶರಣು ಬಂದರೆ, ಕೀಳು ಕುಲದಲ್ಲಿ ಹುಟ್ಟಿದವರೆಂದು ಭಾವಿಸಲ್ಪಡುವವರು, ಸ್ತ್ರೀಯರು, ವೈಶ್ಯರು ಮತ್ತು ಶೂದ್ರರೂ ಪರಮ ಗತಿಯನ್ನು ಸೇರುತ್ತಾರೆ.',
33: 'ಹಾಗಿರುವಾಗ ಪುಣ್ಯಾತ್ಮರಾದ ಬ್ರಾಹ್ಮಣರು ಮತ್ತು ಭಕ್ತರಾದ ರಾಜರ್ಷಿಗಳ ಬಗ್ಗೆ ಹೇಳುವುದೇನಿದೆ! ಶಾಶ್ವತವಲ್ಲದ, ಸುಖವಿಲ್ಲದ ಈ ಲೋಕಕ್ಕೆ ಬಂದಿರುವ ನೀನು ನನ್ನನ್ನು ಭಜಿಸು.',
34: 'ನನ್ನಲ್ಲಿ ಮನಸ್ಸಿಡು, ನನ್ನ ಭಕ್ತನಾಗು, ನನ್ನನ್ನು ಪೂಜಿಸು, ನನಗೆ ನಮಸ್ಕರಿಸು. ಹೀಗೆ ನಿನ್ನನ್ನು ನನ್ನೊಂದಿಗೆ ಜೋಡಿಸಿಕೊಂಡು, ನನ್ನನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸಿದರೆ, ನೀನು ನನ್ನನ್ನೇ ಸೇರುತ್ತೀಯ.',
}
